import sys

def print_a(x):
    print(x)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python a.py <file_name>")
        sys.exit(1)
    with open(sys.argv[1], 'r') as f:
        for line in f:
            print_a(int(line.strip()))

